llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Dronedarone has an absolute oral bioavailability of only ~4% in humans under fasting conditions, attributed to extensive first-pass metabolism; this is the clearest retrieved example of a lipophilic, extensively cleared oral drug falling well below the 20% threshold and supports a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Valomaciclovir stearate, an ester prodrug, achieved >60% oral bioavailability in humans, showing that ester prodrug modification can produce high F; however, its very low structural similarity to the query limits transferability and does not outweigh the low-F evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C52"],
      "claim": "Tiracizine has ~34% systemic availability despite substantial presystemic metabolism, indicating that first-pass metabolism alone does not always force F below 20%; low structural similarity limits its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large lipophilic double prodrug (dabigatran etexilate-like) with ester and carbamate groups; the only clearly low-F retrieved analogue, dronedarone (4% in humans), supports a low prediction, while high-F records come from structurally distant chemotypes and are insufficient to override. Predicted F <20%.",
  "evidence_gaps": [
    "No close structural analogue (Morgan similarity >0.3) is present; all retrieved molecules have similarity around 0.2, so transferability is limited.",
    "No direct experimental record for the query or a dabigatran etexilate-like double prodrug is included.",
    "Most retrieved records report F >20% but from structurally unrelated chemotypes; the only clearly low-F record is dronedarone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

